            k = filt.index('"', j+1) + 1
            # skip spaces
            while k < n and filt[k] == ' ':
                k += 1
            if filt[k:k+1] == '=':
                # value in quotes
                q1 = filt.index('"', k+1)
                q2 = filt.index('"', q1+1)
                fields[key] = [filt[q1+1:q2]]
                i = q2 + 1
            elif filt[k:k+2] == 'IN':
