def parse_filter(filt):
    fields = {}
    # split by ') AND (' or just by ')'
    # Each clause is like ("key" = "val") or ("key" IN LIST 1,2,3)
    # Remove trailing ;
    filt = filt.strip().rstrip(';').strip()
    # Split into clauses by ') AND ('
    clauses = filt.split(') AND (')
    for clause in clauses:
        clause = clause.strip()
        if clause.startswith('('):
            clause = clause[1:]
        if clause.endswith(')'):
            clause = clause[:-1]
        # Now clause is like: "key" = "val" or "key" IN LIST 1,2,3
        # Find key
        q1 = clause.index('"')
        q2 = clause.index('"', q1+1)
        key = clause[q1+1:q2]
        rest = clause[q2+1:].strip()
        if rest.startswith('='):
            # value in quotes
            vq1 = rest.index('"')
            vq2 = rest.index('"', vq1+1)
            fields[key] = [rest[vq1+1:vq2]]
        elif rest.startswith('IN'):
            # LIST numbers
            idx = rest.index('LIST') + 4
            nums_str = rest[idx:].strip()
            nums = [int(x) for x in nums_str.split(',') if x.strip() != '']
            fields[key] = nums
    return fields

